    public ApiResponse<Map<String, Object>> upload(Long docId, MultipartFile file) {
        if (file == null || file.isEmpty()) {
            return ApiResponse.error(400, "文件无效");
        }
        String originalName = file.getOriginalFilename();
        if (originalName == null || originalName.isBlank()) {
            return ApiResponse.error(400, "文件名无效");
        }
        byte[] bytes;
        try {
            bytes = file.getBytes();
        } catch (IOException e) {
            return ApiResponse.error(500, "文件上传失败");
        }
        FileRecord record = new FileRecord();
        record.setDocId(docId);
        record.setOriginalName(originalName);
        record.setStoredName(generateStoredName());
        record.setContentType(file.getContentType());
        record.setFileSize(file.getSize());
        record.setFileData(bytes);
        record.setCreatedAt(LocalDateTime.now());
        fileMapper.insert(record);
        return ApiResponse.success("上传成功", toUploadSummary(record));
    }

    public FileRecord getRecordById(Long id) {
        return fileMapper.findById(id);
    }

    public ApiResponse<List<Map<String, Object>>> listByDocument(Long docId) {
        return ApiResponse.success(toSummaries(fileMapper.findByDocId(docId)));
    }

    public ApiResponse<List<Map<String, Object>>> listAll() {
        return ApiResponse.success(toSummaries(fileMapper.findAll()));
    }

    private String generateStoredName() {
        return System.currentTimeMillis() + "_" + UUID.randomUUID().toString().replace("-", "");
    }

    private Map<String, Object> toUploadSummary(FileRecord record) {
        Map<String, Object> summary = new LinkedHashMap<>();
        summary.put("id", record.getId());
        summary.put("docId", record.getDocId());
        summary.put("originalName", record.getOriginalName());
        summary.put("contentType", record.getContentType());
        summary.put("fileSize", record.getFileSize());
        summary.put("createdAt", record.getCreatedAt());
        return summary;
    }

    private List<Map<String, Object>> toSummaries(List<FileRecord> records) {
        List<Map<String, Object>> summaries = new ArrayList<>();
        for (FileRecord record : records) {
            Map<String, Object> summary = new LinkedHashMap<>();
            summary.put("id", record.getId());
            summary.put("docId", record.getDocId());
            summary.put("originalName", record.getOriginalName());
            summary.put("storedName", record.getStoredName());
            summary.put("contentType", record.getContentType());
            summary.put("fileSize", record.getFileSize());
            summary.put("createdAt", record.getCreatedAt());
            summaries.add(summary);
        }
        return summaries;
    }
}

package com.dochub.platform.util;

import com.dochub.platform.entity.Document;
import com.dochub.platform.entity.User;
import com.dochub.platform.mapper.DocumentMapper;
import com.dochub.platform.mapper.UserMapper;
import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;

@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;
    private final DocumentMapper documentMapper;

    public DataInitializer(UserMapper userMapper, DocumentMapper documentMapper) {
        this.userMapper = userMapper;
        this.documentMapper = documentMapper;
    }

    @Override
    public void run(String... args) {
        if (userMapper.count() == 0) {
            insertUser("admin", "admin123", "ADMIN");
            insertUser("user1", "user123", "USER");
            insertUser("user2", "user456", "USER");
        }
        if (documentMapper.count() == 0) {
            Long user1Id = resolveUserId("user1");
            Long user2Id = resolveUserId("user2");
            insertDocument("入职指南", "欢迎加入团队...", user1Id);
            insertDocument("技术规范", "代码规范文档...", user1Id);
            insertDocument("会议纪要", "本周会议内容...", user2Id);
        }
    }

    private void insertUser(String username, String password, String role) {
        User user = new User();
        user.setUsername(username);
        user.setPassword(password);
        user.setRole(role);
        user.setCreatedAt(LocalDateTime.now());
        userMapper.insert(user);
    }

    private void insertDocument(String title, String content, Long ownerId) {
        Document document = new Document();
        document.setTitle(title);
        document.setContent(content);
        document.setUserId(ownerId);
        LocalDateTime now = LocalDateTime.now();
        document.setCreatedAt(now);
        document.setUpdatedAt(now);
        documentMapper.insert(document);
    }

    private Long resolveUserId(String username) {
        User user = userMapper.findByUsername(username);
        return user != null ? user.getId() : null;
    }
}

package com.dochub.platform.util;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.SecretKey;
import java.nio.charset.StandardCharsets;
import java.util.Date;

@Component
public class JwtUtil {

    public static final String CLAIM_USER_ID = "userId";
    public static final String CLAIM_USERNAME = "username";
    public static final String CLAIM_ROLE = "role";

    private final SecretKey signingKey;
    private final long expiration;

    public JwtUtil(@Value("${jwt.secret}") String secret, @Value("${jwt.expiration}") long expiration) {
        this.signingKey = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
        this.expiration = expiration;
    }

    public String generateToken(Long userId, String username, String role) {
        Date now = new Date();
        Date expiry = new Date(now.getTime() + expiration);
        return Jwts.builder()
                .subject(username)
                .claim(CLAIM_USER_ID, userId)
                .claim(CLAIM_USERNAME, username)
                .claim(CLAIM_ROLE, role)
                .issuedAt(now)
                .expiration(expiry)
                .signWith(signingKey)
                .compact();
    }

    public Claims verifyToken(String token) {
        return Jwts.parser()
                .verifyWith(signingKey)
                .build()
                .parseSignedClaims(token)
                .getPayload();
    }

    public Long getUserId(Claims claims) {
        Object value = claims.get(CLAIM_USER_ID);
        if (value instanceof Number number) {
            return number.longValue();
        }
        return null;
    }

    public String getUsername(Claims claims) {
        Object value = claims.get(CLAIM_USERNAME);
        if (value instanceof String username) {
            return username;
        }
        return claims.getSubject();
    }

    public String getRole(Claims claims) {
        Object value = claims.get(CLAIM_ROLE);
        if (value instanceof String role) {
            return role;
        }
        return null;
    }
}
